// NewCastagnoli returns a Sidecar for the given CRC32 Castagnoli checksum. The
// CRC field is set to the lowercase 8-character hex representation of crc, the
// Type field is set to TypeCastagnoli, and Disabled is false.
func NewCastagnoli(crc uint32) *Sidecar {
