		CRC:  fmt.Sprintf("%08x", crc),
		Type: TypeCastagnoli,
	}
}

// CRC32 parses the CRC field and returns the checksum as a uint32. It returns
// an error if the Type is not recognized, or if the CRC is not exactly 8
// lowercase hexadecimal characters.
func (s *Sidecar) CRC32() (uint32, error) {
